"""Write the reviewable study report from saved results, never manuscript files."""
import hashlib,json,shutil,sys
from pathlib import Path
import numpy as np,pandas as pd
from sklearn.metrics import f1_score,accuracy_score
O=Path(__file__).resolve().parents[1]
def load(n):return json.load(open(O/n))
def table(df,formats=None):
 df=df.copy()
 for c in df.columns:
  if pd.api.types.is_float_dtype(df[c]):df[c]=df[c].map(lambda x:f'{x:.4f}' if pd.notna(x) else '')
 return '| '+' | '.join(map(str,df.columns))+' |\n| '+' | '.join(['---']*len(df.columns))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in df.itertuples(index=False,name=None))
def main():
 prov=load('provenance.json');audit=load('audit_summary.json');summary=load('analysis_summary.json');pairs=load('matched_pair_summary.json');ranks=load('ranked_calculations.json');rows=load('dataset_manifest.json');targets=load('target_selection.json');m=pd.read_csv(O/'metrics.csv');h=pd.read_csv(O/'historical_error_checks.csv');trans=pd.read_csv(O/'error_transitions.csv');boot=pd.read_csv(O/'paired_bootstrap.csv');support=pd.read_csv(O/'training_label_support.csv');ranking=pd.read_csv(O/'score_separation.csv');inv=load('audit_inventory.json');new=load('new_case_version_classification.json');oldfam={r['near_group'] for r in rows[:141]};overall=m[(m.stratum=='all')&(m.population=='original141')&(m.seed.astype(str)!='voting')].groupby('protocol')[['micro_f1','macro_f1','exact_set_accuracy']].mean();npop=m[(m.stratum=='all')&(m.population=='new_queries')&(m.seed.astype(str)!='voting')].groupby('protocol')[['micro_f1','macro_f1','exact_set_accuracy']].mean();primary=boot[(boot.population=='original141')&(boot.before=='old_only_locked')&(boot.after=='expanded_locked')&(boot.scope=='seed_mean')&(boot.metric=='micro_f1')].iloc[0]
 # Retain all earlier model-family prediction evidence and verify its published group scores.
 local=Path(prov['old_raw'])/'model_comparison_20261113';prior=[]
 for method in ['baseline','ExtraTrees','RandomForest','SVM','Logistic','nested']:
  for seed in [20261020,20261021,20261022]:
   p=local/f'{method}_{seed}.npz'
   if p.exists() or (O/'prior_local_evidence'/p.name).exists():
    dst=O/'prior_local_evidence'/p.name
    if not dst.exists():shutil.copyfile(p,dst)
    q=np.load(dst);weights=np.array([1/np.sum(q['families']==g) for g in q['families']]);prior.append(dict(protocol=method,seed=seed,micro_f1=float(f1_score(q['truth'],q['prediction'],average='micro',sample_weight=weights)),sha256=hashlib.sha256(dst.read_bytes()).hexdigest()))
 pd.DataFrame(prior).to_csv(O/'prior_prediction_verification.csv',index=False)
 # Directional cross-label false calls, distinct from missing a label entirely.
 confusions=[]
 for method in ['old_only_locked','expanded_locked']:
  for seed in [20261020,20261021,20261022,'voting']:
   zz=np.load(O/'predictions'/f'{method}_{seed}.npz');species=['CHO','CO','CO2','COCHO','COH','COOH','H','O','OCCOH','OCHO','OH']
   for truth,called in [('COOH','OCHO'),('OCHO','COOH'),('CHO','COH'),('COH','CHO')]:
    a=species.index(truth);b=species.index(called);mask=(zz['truth'][:141,a]==1)&(zz['truth'][:141,b]==0);confusions.append(dict(protocol=method,seed=seed,true_species=truth,false_called_species=called,eligible_records=int(mask.sum()),false_calls=int(np.sum(mask&(zz['prediction'][:141,b]==1)))))
 pd.DataFrame(confusions).to_csv(O/'directional_label_confusions.csv',index=False)
 # Explicit unselected residual candidate comparison on all eligible queries; fallback original input where training templates/gating unavailable.
 residual=[];hidx=6;ohidx=10
 for seed in [20261020,20261021,20261022]:
  baseline=np.load(O/'predictions'/f'expanded_locked_{seed}.npz');p=baseline['prediction'].copy();s=baseline['score'].copy()
  for target in [t for t in targets if t['seed']==seed and t['residual_test_supported']]:
   d=np.load(O/f'residual_diagnostic_{seed}_{target["fold"]}.npz');ix=d['query'];ok=d['template_available'];ss=d['score'];
   for k,j in enumerate([hidx,ohidx]):s[ix[ok],j]=ss[ok,k];p[ix[ok],j]=ss[ok,k]>=target['common_threshold']
  np.savez_compressed(O/'predictions'/f'residual_unselected_diagnostic_{seed}.npz',truth=baseline['truth'],prediction=p,score=s,families=baseline['families'])
  for population,ids in [('original141',np.arange(141)),('new_queries',np.arange(141,len(rows)))]:
   w=np.array([1/np.sum(baseline['families'][ids]==baseline['families'][i]) for i in ids]);yy=baseline['truth'][ids];pp=p[ids]
   for j,sp in [(hidx,'H'),(ohidx,'OH')]:residual.append(dict(seed=seed,population=population,species=sp,original_F1=float(f1_score(yy[:,j],baseline['prediction'][ids,j],sample_weight=w,zero_division=0)),residual_candidate_F1=float(f1_score(yy[:,j],pp[:,j],sample_weight=w,zero_division=0)),omissions=int(np.sum((yy[:,j]==1)&(pp[:,j]==0))),false_positives=int(np.sum((yy[:,j]==0)&(pp[:,j]==1))),interpretation='unselected diagnostic of the second targeted change, all queries retained; original-score fallback for unavailable training templates or failed training-only overlap gate'))
 pd.DataFrame(residual).to_csv(O/'residual_unselected_diagnostic_metrics.csv',index=False)
 sc=[]
 for category in ['substrate','species','species_set','exact_stoichiometry']:
  for r in rows[141:]:
   vals=[r['domain']] if category=='substrate' else r['identity_labels'] if category=='species' else ['+'.join(r['identity_labels'])] if category=='species_set' else ['+'.join(str(v)+k for k,v in sorted(r['observed_counts'].items()))]
   for v in vals:sc.append(dict(category=category,value=v,configuration=r['configuration'],near_group=r['near_group'],new_group=r['near_group'] not in oldfam))
 counts=pd.DataFrame(sc).groupby(['category','value']).agg(configurations=('configuration','nunique'),groups=('near_group','nunique'),new_groups=('new_group','sum')).reset_index();counts.to_csv(O/'new_counts_by_substrate_species_mixture.csv',index=False)
 # Exclusion table distinguishes a pinned reference from an unadmitted training candidate.
 excluded=[]
 for r in inv:
  if not r['old_query'] and not r['eligible_new']:excluded.append(dict(configuration=r['configuration'],status='pinned reference; not a new query' if r['configuration']=='Cu100/Cu100_2x2x4_clean' else 'excluded new candidate',reason=r.get('exclusion','not eligible')))
 pd.DataFrame(excluded).to_csv(O/'exclusions.csv',index=False)
 errorcounts=trans[(trans.population=='original141')&(trans.seed.astype(str)!='voting')].groupby(['before','after','species','change']).size().reset_index(name='seed_case_events');errorcounts.to_csv(O/'error_change_totals.csv',index=False)
 hist=h[(h.population=='original141')&h.protocol.isin(['old_only_locked','expanded_locked','expanded_H_threshold','expanded_residual'])][['protocol','seed','H_mixture_omissions','H_containing_mixtures','CHO_CO_H_exact','CHO_CO_H_sets','false_H_CO_only']]
 seedtable=m[(m.stratum=='all')&(m.population=='original141')&m.protocol.isin(['old_only_locked','expanded_locked'])][['protocol','seed','micro_f1','macro_f1','exact_set_accuracy']]
 topcases=pd.read_csv(O/'existing_CO_H_pair_candidates.csv');anchor=ranks[0]['anchor_configuration'];nearest=topcases[topcases.CO_H==anchor].iloc[0];zero=support[(support.arm=='expanded')&(support.positive_groups==0)][['seed','fold','species']]
 label=pd.read_csv(O/'per_label_metrics.csv');lp=label[(label.population=='original141')&(label.stratum=='all')&(label.seed.astype(str)!='voting')&label.protocol.isin(['old_only_locked','expanded_locked'])].groupby(['species','protocol'])[['recall','precision','omissions','false_positives']].mean().reset_index();lp.to_csv(O/'label_error_change_means.csv',index=False)
 targeted=boot[(boot.population=='original141')&(boot.scope=='seed_mean')&(boot.metric=='micro_f1')&boot.after.isin(['expanded_H_threshold','expanded_residual','expanded_recalibrated'])][['before','after','difference','lower','upper']]
 rawH=pd.DataFrame(residual);rawH=rawH[rawH.population=='original141'].groupby('species')[['original_F1','residual_candidate_F1','omissions','false_positives']].mean().reset_index()
 lines=[ '# Fixed-query data addition and recurring-error study', '',f'**Added training data did not establish an improvement on the fixed original queries.** Thirteen usable configurations (twelve new near-geometry groups, plus one additional view of an old group) change three-seed group-weighted micro F1 from **{overall.loc["old_only_locked","micro_f1"]:.4f} to {overall.loc["expanded_locked","micro_f1"]:.4f}**. Paired change **{primary.difference:+.4f}**, conditional 95% geometry-group bootstrap interval **[{primary.lower:+.4f}, {primary.upper:+.4f}]**. CHO and OH omissions decrease, but additional CHO/CO false positives and other omissions offset that benefit. H-containing mixture recovery remains poor; complete CHO+CO+H recovery remains 1/8 for every seed.','',f'**Single most informative next calculation:** calculate the CO-only counterpart of `{anchor}` on the same parent with **{ranks[0]["n_CO"]} CO molecules**, preserving its CO coordinates/sites for the first vertical diagnostic and removing only isolated H. Then obtain a separately relaxed counterpart. The existing CO+H query misses H in all three expanded-model seeds and has no adequate matched CO-only control. Do not use that already-seen anchor as prospective independent validation; reserve a wholly new matched family for that purpose. No jobs were submitted.','', '## Provenance and scope','', f'- Repository: `HailiJia/CO2RR_XAS_agent`, draft PR #18, verified base head `{prov["base_commit"]}`. This study is new work above that head; it does not replace an archived benchmark.', '- Frozen reference cohort: `study/dataset_20261101`, 141 configurations / 135 conservative near-geometry groups. Training-array SHA256: `'+prov['previous_inputs_sha256']+'`.', '- November 13 model-comparison report was found locally in `CO2RR_11103/model_comparison_20261113/REPORT.md`, outside the checkout and absent from the base PR head. Report, producing scripts and all 18 family/seed prediction files are preserved in `prior_local_evidence/`; `prior_prediction_verification.csv` recomputes their group scores. Its scores concern unchanged-cohort architecture selection, **not** adding data. The earlier first rerun used different inner membership and record weighting; it is not the fixed-protocol comparison here.', '- New source: local author export `CO2RR_1113`. The raw full dataset was not present at the base PR commit. Selected geometry/spectrum/source evidence hashes are in `source_manifest.json`; `inputs.npz` and full manifests contain the actual saved analysis inputs. Raw large electronic logs/wavefunctions are not duplicated.', '', '## 1. What the data added','',f'The audit produces **154 configurations / 147 near groups** in total. Of the 13 added records, **9** already had complete top-two spectra in the November 3 export but were absent from the frozen November 1 cohort; **4** first acquired both top-two spectra in the November 13 export. The latter are CHO/CHO_0p111_interface_Cu, CO_OH/CO_OH_0p194_4CO_3OH_AuCu2, OCCO_CO/OCCO_CO_0p111_AuCu_interface and OH/OH_0p25_interface_biased. All added configurations are CuAu; **zero new Cu100 training configurations** pass this task audit.', '',f'There are **{audit["additional_layer_spectra"]} additional convolved layer spectra** relative to November 3, of which **{audit["new_top_two_layer_spectra"]}** supply those four newly complete top-two pairs. Other deeper layers are extra observations of existing physical configurations, not independent training cases. `COOH/COOH_0p111_Cu_uniform` is within RMS 0.01398 Å / max 0.09377 Å of an existing COOH near group, so it adds a record view, not a new group, and the canonical one-view training rule retains the original view.', '',table(counts[counts.category.isin(['substrate','species_set','species'])]), '', 'Exact molecular stoichiometries, separate from species-presence sets, are in `new_counts_by_substrate_species_mixture.csv` and `new_cohort_counts.csv`. Species totals overlap because mixtures contain multiple labels. Groups are geometry clusters, not independent clean-parent families.', '', '**Geometry/label checks:** all 141 frozen XAS geometries match their supplied top-layer input geometry, and all 141 frozen label sets agree with the observed XAS-input graph. A newer root CONTCAR is never substituted into a frozen query. The historical H_0p25/interface_biased2 root/XAS discrepancy is retained as originally audited and explicitly listed. For new cases, require stable graph labels under the existing ±10% bond-cutoff check, an exact root-relaxed CONTCAR/XAS mapping, and agreement between top-two input geometries. CHO is identified by C–H and COH by O–H connectivity, not folder name. The new CHO folders contain 2CHO+2CO+2H; the OCCO_CO folder contains 4CO, not intact OCCO. Initial-versus-XAS connectivity and supplied-label disagreements are recorded per case in `audit_inventory.json`.', '', '**Reference and population checks:** every newly admitted layer covers all 36 physical Cu sites; top-two populations are 36+36. Raw source grids are complete, site/log E_cut mappings pass, and all new raw source symmetry multiplicities equal one. Thus native aggregate divided by physical N is already the per-Cu scale; no guessed aggregate symmetry correction is needed. Independent reconvolution was not run in this study. Pin the previously audited clean physical curves only after source hashes match; reject cross-cell/composition/settings/grids. CuAu and Cu100 keep separate clean references. The incomplete redundant Cu100 clean native source is not used. Neither CONTCAR availability nor complete spectra establishes a relaxation stopping criterion; no new convergence or independent-parent-transfer claim is made.', '', '**Exclusions:** `exclusions.csv` lists every non-old candidate that fails the task audit, including missing top-two spectra, root/XAS lineage mismatch, unsupported H2O/CO3 chemistry and an invalid OH layer population. The clean Cu100 entry is a pinned reference, not an added independent query. None of the original 141 queries is removed because of model errors.', '',table(pd.DataFrame(excluded)), '', '## 2. Adding training data on fixed queries','', 'Both arms retain the exact original 141 spectra, labels, test-query fold assignments and original seed/fold thresholds. Model: independent balanced 64-tree ExtraTrees, leaf size 1, max_features=sqrt; verified population-weighted physical top-two Cu K-edge reaction-minus-clean spectra, training-only signed RMS floor, Combined spectrum/integral/first/second derivative features. Seeds: 20261020/21/22. Every old-only probability and binary prediction reproduces the verified November 13 local baseline exactly.', '', 'Five inherited near groups have related query views assigned to different original outer folds. Moving them would violate the fixed-query-fold requirement. We therefore keep those query folds and **purge the entire held-out related group from every training fit**, exactly as the canonical baseline did. No outer or inner fit has a shared train/validation/test geometry family. Related new views inherit old grouping; new unrelated groups use a deterministic geometry-group hash fold. The inherited conflict inventory and exact memberships are saved; these folds must not be described as disjoint test-group partitions. Bootstrap resamples whole near groups, preserving their correlated views.', '', 'New data enter only permitted training folds. One canonical view per group prevents the additional COOH view from silently increasing its weight. Original fold-specific thresholds are transferred unchanged to both arms. Separate common-threshold recalibration uses inner grouped predictions only; it does not enter the primary added-data comparison.', '',table(overall.reset_index()), '', 'All figures in the table are three-seed means, with each geometry group carrying total evaluation weight one. Macro F1 includes all eleven frozen labels, including unsupported-in-a-fold positives; exact-set accuracy requires every label to match. Seed variation and majority voting are separate:', '',table(seedtable), '', 'Voting probabilities are not averaged and rethresholded: voting means at least two of three predeclared binary predictions. The saved mean score is diagnostic only. `paired_bootstrap.csv` reports paired micro/macro/exact-set intervals, conditional on fixed OOF predictions; these intervals do not incorporate retraining, independent-parent or measured-experiment uncertainty.', '', '**New queries, evaluated separately:** thirteen new records form thirteen test groups within that subset (one group is shared with the old cohort). Their difficulty does not change the primary test population. Macro F1 still averages eleven labels, so absent-label zeros lower it; it is not directly comparable with full-cohort macro F1.', '',table(npop.loc[['old_only_locked','expanded_locked']].reset_index()), '', '## 3. Errors before targeted changes','',table(hist), '', 'The original pattern is reproduced exactly: each seed omits H in 8/16 H-containing mixtures and recovers only 1/8 CHO+CO+H sets. Expanded training gives 9/8/7 H omissions and still 1/8 complete triple-mixture recovery. False H on 32 CO-only original queries rises from 1/4/1 to 2/5/2. Voting omits H in 8/16 mixtures and still recovers only 1/8 triple mixtures.', '', 'Mean original-query CHO omissions decrease from 5.67 to 4.33 per seed and OH omissions from 4.00 to 2.33, but CHO false positives increase from 1.33 to 3.33 and CO false positives from 8.67 to 10.00. O, OCHO and COOH omissions also increase slightly. `per_case_predictions_errors.csv`, `errors_long.csv`, `error_transitions.csv` and the four `error_breakdown_*.csv` files preserve per-species, exact stoichiometry/species set, substrate and pure/mixed detail.', '', 'H has training positives in every outer fold (25–34 positive training groups in expanded fits). Expanded inner H AUC is 0.818–0.918 (mean 0.872), so common-cutoff calibration is a plausible limited test, but CO-containing mixture scores still overlap CO-only negatives. Original-query OOF H AUC is diagnostic, not a selection criterion: all-case AUC improves from 0.917 to 0.928; CO-containing AUC from 0.831 to 0.836. Those aggregate rankings do not imply complete mixture recovery at acceptable false-positive rates.', '', 'There remain only two pure CHO configurations, and the new CHO positives are mixtures rather than new pure CHO controls. COCHO still has one positive geometry group; its held-out-positive fold has zero COCHO training positives in both arms, so zero held-out COCHO recall cannot establish a learned positive class. Missing supports and per-fold rare-label limitations are saved in `training_label_support.csv`.', '', '## 4. Two targeted changes, selected within training only','', '**H-specific cutoff:** keep all other labels at the original common threshold. Permit H offsets ±0.05/0.10 (including unchanged), require inner H ranking/support, optimize group-weighted inner H F1, and allow at most one extra group-weighted CO-only false H call in inner validation. The selected thresholds frequently increase rather than decrease: the training objective favors specificity. On original queries this corrects **zero H omissions** and adds **zero false H calls**; it removes five false H calls across the three seed/case evaluations (one on CO-only in seed20 and three on CO-only in seed21) but introduces one H omission in seed22. It therefore does not repair the recurring missed-mixture mechanism. Voting H-mixture omissions, CO-only false calls and triple-mixture exact recovery are unchanged.', '', '**CO-template residual for H/OH:** if CO-conditioned H inner AUC is below 0.80, form a substrate-matched pure-CO mean template from training groups only. Fit a nonnegative scalar to each common-scale signed spectrum, subtract the CO template, then apply training-floor signed RMS and Combined features. Each training example uses templates excluding its entire geometry group; inner validation templates exclude all validation groups. Require at least two pure-CO training groups for a template; unsupported cases retain original scores rather than being dropped. Fit the same 64-tree estimator for H/OH and retain the original cutoff. Switch a label to residual scores only if inner group-weighted label F1 improves by at least .02, with the H false-call constraint. This is a test of an additive template hypothesis on actual relaxed mixtures, not synthetic sums.', '',f'The overlap gate permits residual evaluation in {sum(t["residual_test_supported"] for t in targets)}/15 seed/fold fits. H residual replacement is selected in **{sum(t.get("residual_selection",{}).get("H",{}).get("enabled",False) for t in targets)}** fits; OH in **{sum(t.get("residual_selection",{}).get("OH",{}).get("enabled",False) for t in targets)}** fits. The selected residual arm does not improve original-query micro F1 or H-mixture recovery. An unselected residual-candidate diagnostic, with original-score fallback and all queries retained, is saved separately; it is not used to choose an outer-test winner:', '',table(rawH), '', 'Paired changes below are relative to the expanded locked-threshold arm; recalibration is explicitly separate from the data-addition effect:', '',table(targeted), '', 'Both changes are exploratory targeted analyses prompted by known recurring errors, not prospective confirmation. No architecture sweep or outer-score optimization was added.', '', '## 5. Matched contrasts and ranked calculations','',f'We searched **{pairs["same_loading_candidate_pairs"]} actual same-substrate/same-CO-count CO-only versus CO+H candidate pairs** among {pairs["CO_only_cases"]} CO-only and {pairs["actual_CO_H_cases"]} CO+H configurations. Four share an initial metal-parent hash, but none simultaneously matches parent, environment, contact composition and relaxed CO-site distances (carbon RMS≤0.5 Å and max≤1 Å). There are **zero adequate existing matched pairs** under those disclosed criteria; initial parent hashing itself is not a trajectory-level lineage proof.', '',f'For the proposed anchor, the best parent-prioritized available CO-only comparison is `{nearest.CO_only}`. Its CO-site RMS mismatch is **{nearest.CO_carbon_RMS_A:.2f} Å**, so its shared-scale spectral difference **{nearest.shared_scale_difference_RMS:.6f} RMS** cannot be attributed uniquely to H. Comparable-loading/environment CO-only variation is **{nearest.CO_only_variation_median:.6f} median RMS**. The saved hypothetical ±0.1/0.2 eV registration scenarios reach **{nearest.synthetic_shift_sensitivity_max_RMS:.6f} RMS** for that CO-only curve; a 1% gain scenario is also saved. These are explicitly simulated sensitivities, **not measured noise or energy-registration estimates**. The 0.2 eV energy grid is sampling, not an uncertainty estimate. Actual pair curves and signed differences are saved before unit-RMS normalization in `matched_pair_spectra.npz`; nearest unmatched controls are never called H-only contrasts.', '', 'The calculation list is prepared only; no scheduler, electronic calculation, remote portal, manuscript, SI or publication-figure update was invoked.']
 for r in ranks:lines+=['',f'### Priority {r["rank"]}: {r["calculation"]}', '', '**Hold fixed:** '+r['hold_fixed']+'.', '', '**Vary:** '+r['vary']+'.', '', '**Decision:** '+r['decision_changing_result'], '', '**Prospective split:** '+r['reservation']+'.']
 lines+=['', 'COOH/OCHO currently suffers primarily from omissions: expanded voting omits COOH in 6/9 positives and OCHO in 4/8. Direct cross-label confusion is rarer (one false OCHO call among COOH positives, zero reverse calls in voting). `directional_label_confusions.csv` separates these mechanisms, so these controls remain below H and pure CHO in priority. COCHO additions are conditional on that species being central to the claim; a sole positive group does not justify broad identification claims.', '', '## Reproduction and saved evidence','', 'Use the repository at the recorded base commit plus this study. Python 3.13, NumPy 2.3.5 and scikit-learn 1.8.0 were used; exact dependency versions are in `requirements.txt` and `evaluation_protocol.json`. No network access is needed to refit from the saved audited arrays.', '', '```sh', 'python -m pip install -r study/fixed_query_error_study_20261113/requirements.txt', 'python study/fixed_query_error_study_20261113/code/train.py', 'python study/fixed_query_error_study_20261113/code/analyze.py', 'python study/fixed_query_error_study_20261113/code/matched_pairs.py', 'python study/fixed_query_error_study_20261113/code/report.py', 'python study/fixed_query_error_study_20261113/code/verify.py', '```', '', 'These commands overwrite only this new study’s regenerated outputs; preserve a copy first if changing inputs/code. To repeat source admission with both raw exports present, run `code/audit.py --old-raw /path/CO2RR_11103 --new-raw /path/CO2RR_1113` first. The saved immutable query inputs avoid substituting changed root geometries. Models, held-out probabilities/labels, per-case errors, inner scores, fold/template memberships, source hashes, original thresholds, dependency versions and ranked calculation JSON/CSV are included. Every model is reloaded and its held-out scores replayed exactly. `verification.json` checks original input identity, all fold/template group guards, selected source hashes, and unchanged original tracked manuscript/SI/figure/benchmark files. `ARTIFACTS.json` records this study’s saved files.']
 (O/'REPORT.md').write_text('\n'.join(lines)+'\n');print('Wrote REPORT.md',flush=True)
if __name__=='__main__':main()
